// WP-42: PQSCity.cs / PQSCity2.cs (the placement data and maths of the KSC, the airfield and every set-dressing / launch-site
// object on a PQS sphere) and the CelestialBody.GetRandomLatitudeAndLongitude helper they use.
//
// Data (CLAUDE.md "Original game assets"): StockPQSCities() is the table of the serialized fields of every stock PQSCity /
// PQSCity2 component, generated by tools/wp42/gen_wp42_cities.py from data/terrain/pqs_prefab.json (Unity prefab values read
// from KSP_x64_Data/sharedassets9.assets by tools/wp11/extract_terrain.py).
//
// Engine seams (documented, owned by WP-47 scene / WP-12 colliders): the Unity Transform tree is not modelled. A PQSCity
// keeps its transform.localPosition / localRotation (the PQS sphere is the parent, unscaled) and derives latitude / longitude /
// altitude from the local position, i.e. as if transform.position == body-relative position in an identity body frame; a host
// that has real transforms installs `worldPositionOf` so CelestialBody.GetLatLonAlt sees the engine's (floating-origin float)
// world position instead. The raycast of PQSCity2.OrientateRayCast and the water branch OrientateOnWater are engine physics and
// are hooks / deferred (see STATUS.md).
#pragma once

#include <array>
#include <functional>
#include <string>
#include <vector>

#include "ksp/dotnet/random.hpp"
#include "ksp/math/util_math.hpp"
#include "ksp/math/vector3d.hpp"
#include "ksp/unity/quaternion.hpp"
#include "ksp/unity/vector.hpp"

namespace ksp {

class CelestialBody;
class PQS;
class LaunchSite;

// the serialized fields of one stock PQSCity / PQSCity2 component (generated table, see the file comment)
struct PQSCityPrefab {
    const char* bodyName;
    const char* gameObject;      // "Kerbin/KSC" (the GameObject path from the PQS root)
    const char* name;            // GameObject.name
    bool isCity2;                // PQSCity2 (else PQSCity)
    int modIndex;                // index in the PQS childMods list of data/terrain/pqs_prefab.json
    int order;
    // the embedded LaunchSite fields serialized on the component (most are blank: the stock LaunchSites live in PSystemSetup)
    const char* launchSiteTransformURL;
    bool requiresPOIVisit;
    const char* poiName;
    int nodeType;
    int editorFacility;
    const char* spaceCenterFacilityName;
    bool useIndividualPOIRange;
    float individualPOIRange;
    // PQSCity
    bool randomizeOnSphere, repositionToSphere, repositionToSphereSurface, repositionToSphereSurfaceAddHeight, reorientToSphere;
    std::array<float, 3> repositionRadial;
    double repositionRadiusOffset;
    std::array<float, 3> reorientInitialUp;
    float reorientFinalAngle;
    float frameDelta;
    // PQSCity2
    const char* objectName;
    const char* displayobjectName;
    double lat, lon, alt;
    std::array<float, 3> up;
    double rotation;
    bool snapToSurface, raycastSurface, setOnWaterSurface;
    double snapHeightOffset;
    bool baseRotFacesNorthPole;
};
const std::vector<PQSCityPrefab>& StockPQSCities();

// The PSystemSetup.SpaceCenterFacility a city is bound to (PQSCity.spaceCenterFacility / PQSCity2.spaceCenterFacility): only the two members
// Orientate reads, `facilityTransform != null` and SetSpawnPointsLatLonAlt(). Unset (null functions) = spaceCenterFacility == null.
struct SpaceCenterFacilityLink {
    std::function<bool()> hasFacilityTransform;
    std::function<void()> setSpawnPointsLatLonAlt;
    // PQSCity.cs:341-344 / PQSCity2.cs:251-254
    void OrientateSetSpawnPoints() const {
        if (setSpawnPointsLatLonAlt && hasFacilityTransform && hasFacilityTransform()) setSpawnPointsLatLonAlt();
    }
};

// PQSCity.cs:11 (the placement part: Orientate, Randomize, seeds). transform.localPosition / localRotation are float32.
class PQSCity {
public:
    PQSCity(const PQSCityPrefab& prefab, CelestialBody* body, PQS* sphere);

    std::string name;                         // gameObject.name (:131 SurfaceObjectName)
    bool randomizeOnSphere = false;           // :73
    bool repositionToSphere = true;           // :75
    bool repositionToSphereSurface = false;   // :77
    bool repositionToSphereSurfaceAddHeight = false;   // :79
    Vector3f repositionRadial{0.0f, 0.0f, -1.0f};      // :81 (Reset(): Vector3.back)
    double repositionRadiusOffset = 0.0;      // :83
    bool reorientToSphere = true;             // :85
    Vector3f reorientInitialUp{0.0f, 1.0f, 0.0f};      // :87
    float reorientFinalAngle = 0.0f;          // :89
    double lat = 0.0, lon = 0.0, alt = 0.0;   // :91-95
    bool useIndividualPOIRange = false;
    float individualPOIRange = 100.0f;
    LaunchSite* launchSite = nullptr;         // :99
    SpaceCenterFacilityLink spaceCenterFacility;   // PQSCity.spaceCenterFacility
    CelestialBody* body = nullptr;            // :129 (celestialBody)
    PQS* sphere = nullptr;
    Vector3d planetRelativePosition;          // PQSSurfaceObject.planetRelativePosition
    Vector3f localPosition;                   // transform.localPosition
    Quaternionf localRotation = Quaternionf::identity();   // transform.localRotation

    // seams ----------------------------------------------------------------------------------------------------------------
    // PQS.GetSurfaceHeight(radial, overrideQuadBuildCheck: true) (default: sphere->GetSurfaceHeight(radial))
    std::function<double(const Vector3d&)> sphereSurfaceHeight;
    // transform.position (the world position the engine computed for the localPosition); unset = identity body frame
    std::function<Vector3d(const PQSCity&)> worldPositionOf;
    // CelestialBody.GetLatitudeAndLongitude / GetLatLonAlt of the city (called by Orientate)
    void LatLonAlt(double& latitude, double& longitude, double& altitude) const;

    void ResetCelestialBody() {}                                 // :146 (the host assigns `body`)
    void Orientate(bool allowReposition = true);                 // :306
    void Randomize();                                            // :272
    static int GetPQSCitySeed(const PQSCity& city);              // :378
    static int GetPQSCitySeed(const std::string& name, const std::string& body);   // :387
    static int GetStableHashCode(const std::string& str, bool Bit32 = false);      // :395
    // PQSCity.POIRange (PQSCity.cs:101: poiRange unless the individual range is used)
    double poiRange = 0.0;
    double POIRange() const { return useIndividualPOIRange ? static_cast<double>(individualPOIRange) : poiRange; }
};

// PQSCity2.cs:6 (placement data; Orientate is the surface-snap branch, the raycast / water branches are hooks)
class PQSCity2 {
public:
    PQSCity2(const PQSCityPrefab& prefab, CelestialBody* body, PQS* sphere);

    std::string name;                  // gameObject.name
    std::string objectName;            // :18
    std::string displayobjectName;     // :20
    double lat = 0.0, lon = 0.0, alt = 0.0;   // :22-26
    Vector3f up{0.0f, 1.0f, 0.0f};     // :28
    double rotation = 0.0;             // :30
    bool snapToSurface = false;        // :34
    bool raycastSurface = false;       // :36
    bool setOnWaterSurface = false;    // :38
    double snapHeightOffset = 0.0;     // :40
    bool baseRotFacesNorthPole = false;   // :42
    bool useIndividualPOIRange = false;
    float individualPOIRange = 100.0f;
    double poiRange = 0.0;
    LaunchSite* launchSite = nullptr;  // :46
    SpaceCenterFacilityLink spaceCenterFacility;   // PQSCity2.spaceCenterFacility
    CelestialBody* body = nullptr;     // :123
    PQS* sphere = nullptr;
    Vector3d planetRelativePosition;
    Vector3f localPosition;
    Quaternionf localRotation = Quaternionf::identity();
    bool raycastCompleted = false, positioningCompleted = false, positionedWhenVisible = false, inVisibleRange = false;

    std::function<double(const Vector3d&)> sphereSurfaceHeight;      // PQS.GetSurfaceHeight(.., true)
    std::function<Vector3d(const PQSCity2&)> worldPositionOf;        // transform.position
    // OrientateRayCast (:365): the physics raycast onto the mobile launch pad collision layer; returns the corrected surface height
    // (the hook sets raycastCompleted when the ray hit; unset: it hits nothing, the height is unchanged and raycastCompleted stays false)
    std::function<double(const Vector3d& surfPosNorm, double surfaceHeight, bool& raycastCompleted)> orientateRayCast;
    // PositionMobileLaunchPad.CompleteOrientation / ResetPositioning etc. are scenery work (WP-47)
    std::function<void()> onPositioned;

    double POIRange() const { return useIndividualPOIRange ? static_cast<double>(individualPOIRange) : poiRange; }   // :133
    void Reset();                                                // :390
    void Orientate();                                            // :186
    void LatLonAlt(double& latitude, double& longitude, double& altitude) const;
};

// CelestialBody.cs:799 GetRandomLatitudeAndLongitude (the KSPRandom draw loop; SpaceCenter.Instance and the PQS terrain height are
// read through SpaceCenter / CelestialBody::TerrainAltitude)
void GetRandomLatitudeAndLongitude(CelestialBody& body, double& latitude, double& longitude, bool waterAllowed = false,
                                   bool spaceCenterAllowed = false, KSPRandom* generator = nullptr);

// LatLon.cs:13 GetSurfaceNVector(Planetarium.CelestialFrame, lat, lon) with the frame PQSCity uses (SetFrame(0, 0, 0))
Vector3d LatLonGetSurfaceNVector(const CelestialFrame& cf, double lat, double lon);

}  // namespace ksp
